import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/cyclehire_w001.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Compute Departures, Self-contained trips, Arrival share, and Expected self-contained trips for each borough
boroughs = data['StartBorough'].unique()
data_points_used = len(data)

departures = {}
self_contained_trips = {}
arrival_share = {}
expected_self_contained_trips = {}
self_containment_index = {}

for borough in boroughs:
    departures[borough] = len(data[data['StartBorough'] == borough])
    self_contained_trips[borough] = len(data[(data['StartBorough'] == borough) & (data['EndBorough'] == borough)])
    arrival_share[borough] = len(data[data['EndBorough'] == borough]) / len(data)
    expected_self_contained_trips[borough] = departures[borough] * arrival_share[borough]
    self_containment_index[borough] = self_contained_trips[borough] / expected_self_contained_trips[borough]

# Calculate the Self-Containment Index for each borough
self_containment_index = {borough: index for borough, index in self_containment_index.items() if index != 0}

# Identify HOT SPOT and COLD SPOT boroughs
hot_spots = []
cold_spots = []

for borough in boroughs:
    neighbors = adjacency[adjacency['borough'] == borough]['neighbor'].tolist()
    avg_self_containment_index = np.mean([self_containment_index[neighbor] for neighbor in neighbors if neighbor in self_containment_index])

    if self_containment_index[borough] > 1 and avg_self_containment_index > 1:
        hot_spots.append((borough, self_containment_index[borough]))
    elif self_containment_index[borough] < 1 and avg_self_containment_index < 1:
        cold_spots.append((borough, self_containment_index[borough]))

# Test for statistical significance using a permutation/randomization test
def moran_i(data, weights):
    n = len(data)
    sum_x = sum(data)
    sum_w = sum(weights)
    sum_xw = sum([x * w for x, w in zip(data, weights)])
    sum_w2 = sum([w**2 for w in weights])
    sum_x2 = sum([x**2 for x in data])
    sum_xw2 = sum([x**2 * w for x, w in zip(data, weights)])
    numerator = n * sum_xw2 - sum_x * sum_xw
    denominator = n * sum_w2 - sum_w**2
    return numerator / denominator

for borough, index in self_containment_index.items():
    weights = [self_containment_index[neighbor] for neighbor in adjacency[adjacency['borough'] == borough]['neighbor'].tolist() if neighbor in self_containment_index]
    moran_i_value = moran_i([index] + weights, [1] + [1 for _ in weights])
    p_value = np.mean([moran_i([index] + [np.random.choice(weights) for _ in weights], [1] + [1 for _ in weights]) for _ in range(500)])
    if p_value < 0.05:
        if index > 1:
            hot_spots.append((borough, index, moran_i_value, p_value))
        else:
            cold_spots.append((borough, index, moran_i_value, p_value))

# List the identified HOT SPOT and COLD SPOT boroughs
hot_spots.sort(key=lambda x: x[1], reverse=True)
cold_spots.sort(key=lambda x: x[1])

print(f"data_points_used = {data_points_used}")
for borough, index, moran_i_value, p_value in hot_spots:
    print(f"HOT SPOT: {borough} (HH, statistical method={moran_i_value}, p-value={p_value})")
for borough, index, moran_i_value, p_value in cold_spots:
    print(f"COLD SPOT: {borough} (LL, statistical method={moran_i_value}, p-value={p_value})")

if not hot_spots and not cold_spots:
    print("FINAL ANSWER: none")
else:
    print("FINAL ANSWER: ", end="")
    for i, (borough, _, _, _) in enumerate(hot_spots):
        print(f"{borough} (HH, statistical method={hot_spots[i][2]})", end="")
        if i < len(hot_spots) - 1:
            print(", ", end="")
    for i, (borough, _, _, _) in enumerate(cold_spots):
        print(f"{borough} (LL, statistical method={cold_spots[i][2]})", end="")
        if i < len(cold_spots) - 1:
            print(", ", end="")
    print()
